"""Stock reservations for the example catalog."""

from __future__ import annotations

STOCK: dict[str, int] = {"fern-01": 4, "moss-02": 0}


def reserve(sku: str, quantity: int) -> int:
    """Reserve available stock and return what is left."""
    if quantity < 1:
        raise ValueError("a reservation quantity must be positive")

    available = STOCK.get(sku, 0)
    if quantity > available:
        raise ValueError("not enough stock to complete the reservation")

    STOCK[sku] = available - quantity
    return STOCK[sku]

