"""Discounted prices for the example catalog."""

from __future__ import annotations


def discounted(price: float, percent: float) -> float:
    """Apply a percentage discount between zero and one hundred."""
    if percent < 0:
        raise ValueError("a discount cannot be negative")
    if percent > 100:
        raise ValueError("a discount cannot exceed one hundred percent")
    return round(price * (1 - percent / 100), 2)

